package demo.pharma.purchase;
import demo.pharma.audit.AuditService; import demo.pharma.catalog.*; import demo.pharma.common.exception.*; import demo.pharma.inventory.*; import demo.pharma.supplier.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import lombok.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.math.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/purchases") @RequiredArgsConstructor public class PurchaseLifecycleController {private final PurchaseOrderRepository orders;private final SupplierRepository suppliers;private final MedicineRepository medicines;private final MedicineBatchRepository batches;private final InventoryService inventory;private final AuditService audit;
 record Line(@NotNull UUID medicineId,@NotNull@Positive BigDecimal quantity,@NotNull@PositiveOrZero BigDecimal unitPrice,@PositiveOrZero BigDecimal discount,@PositiveOrZero BigDecimal tax){}record UpdateRequest(@NotNull UUID supplierId,@NotNull LocalDate orderDate,LocalDate expectedDeliveryDate,String notes,@NotEmpty List<@Valid Line> items){}record ItemView(UUID id,UUID medicineId,String medicineName,BigDecimal quantity,BigDecimal receivedQuantity,BigDecimal unitPrice,BigDecimal discount,BigDecimal tax,BigDecimal total){}record Detail(UUID id,String purchaseOrderNumber,UUID supplierId,String supplierName,LocalDate orderDate,LocalDate expectedDeliveryDate,PurchaseOrderStatus status,BigDecimal subtotal,BigDecimal discount,BigDecimal tax,BigDecimal total,String notes,List<ItemView> items){}record ReceiveLine(@NotNull UUID purchaseOrderItemId,@NotBlank String batchNumber,LocalDate manufacturingDate,@NotNull LocalDate expiryDate,@NotNull@Positive BigDecimal quantity,@NotNull@PositiveOrZero BigDecimal purchasePrice,@NotNull@PositiveOrZero BigDecimal mrp,@NotNull@PositiveOrZero BigDecimal sellingPrice){}record ReceiveRequest(@NotEmpty List<@Valid ReceiveLine> items){}
 @GetMapping("/{id}/detail")@PreAuthorize("hasAuthority('PURCHASE_VIEW')")@Transactional(readOnly=true) Detail detail(@PathVariable UUID id){return view(find(id));}
 @PutMapping("/{id}")@PreAuthorize("hasAuthority('PURCHASE_UPDATE')")@Transactional Detail update(@PathVariable UUID id,@Valid@RequestBody UpdateRequest r){PurchaseOrder p=find(id);if(p.getStatus()!=PurchaseOrderStatus.DRAFT&&p.getStatus()!=PurchaseOrderStatus.PENDING_APPROVAL)throw new BusinessException("Only draft or pending orders can be edited");p.setSupplier(suppliers.findById(r.supplierId()).orElseThrow(()->new NotFoundException("Supplier",r.supplierId())));p.setOrderDate(r.orderDate());p.setExpectedDeliveryDate(r.expectedDeliveryDate());p.setNotes(r.notes());p.getItems().clear();totals(p,r.items());orders.save(p);audit.logCurrent("PURCHASE_UPDATED","PURCHASE_ORDER",id,null,p.getPurchaseOrderNumber());return view(p);}
 @PostMapping("/{id}/receive-items")@PreAuthorize("hasAuthority('PURCHASE_RECEIVE')")@Transactional Detail receivePartial(@PathVariable UUID id,@Valid@RequestBody ReceiveRequest r){PurchaseOrder p=find(id);if(p.getStatus()!=PurchaseOrderStatus.APPROVED&&p.getStatus()!=PurchaseOrderStatus.ORDERED&&p.getStatus()!=PurchaseOrderStatus.PARTIALLY_RECEIVED)throw new BusinessException("Purchase must be approved before receiving");for(ReceiveLine l:r.items()){PurchaseOrderItem item=p.getItems().stream().filter(i->i.getId().equals(l.purchaseOrderItemId())).findFirst().orElseThrow(()->new BusinessException("Purchase item does not belong to this order"));if(l.manufacturingDate()!=null&&!l.expiryDate().isAfter(l.manufacturingDate()))throw new BusinessException("Expiry date must be after manufacturing date");if(item.getReceivedQuantity().add(l.quantity()).compareTo(item.getQuantity())>0)throw new BusinessException("Received quantity exceeds ordered quantity");MedicineBatch batch=batches.findByMedicineIdAndBatchNumber(item.getMedicine().getId(),l.batchNumber()).orElseGet(()->newBatch(p,item,l));if(batch.getId()==null)batch=batches.save(batch);inventory.receive(batch,l.quantity(),p.getId());item.setReceivedQuantity(item.getReceivedQuantity().add(l.quantity()));}boolean complete=p.getItems().stream().allMatch(i->i.getReceivedQuantity().compareTo(i.getQuantity())>=0);p.setStatus(complete?PurchaseOrderStatus.RECEIVED:PurchaseOrderStatus.PARTIALLY_RECEIVED);orders.save(p);audit.logCurrent("PURCHASE_RECEIVED","PURCHASE_ORDER",id,null,p.getStatus().name());return view(p);}
 private MedicineBatch newBatch(PurchaseOrder p,PurchaseOrderItem item,ReceiveLine l){MedicineBatch b=new MedicineBatch();b.setMedicine(item.getMedicine());b.setSupplier(p.getSupplier());b.setBatchNumber(l.batchNumber().trim());b.setManufacturingDate(l.manufacturingDate());b.setExpiryDate(l.expiryDate());b.setPurchasePrice(l.purchasePrice());b.setMrp(l.mrp());b.setSellingPrice(l.sellingPrice());b.setQuantity(BigDecimal.ZERO);return b;}private void totals(PurchaseOrder p,List<Line> lines){BigDecimal subtotal=BigDecimal.ZERO,tax=BigDecimal.ZERO,discount=BigDecimal.ZERO;for(Line l:lines){PurchaseOrderItem i=new PurchaseOrderItem();i.setPurchaseOrder(p);i.setMedicine(medicines.findById(l.medicineId()).orElseThrow(()->new NotFoundException("Medicine",l.medicineId())));i.setQuantity(l.quantity());i.setReceivedQuantity(BigDecimal.ZERO);i.setUnitPrice(l.unitPrice());i.setDiscount(n(l.discount()));i.setTax(n(l.tax()));i.setTotal(l.unitPrice().multiply(l.quantity()).subtract(n(l.discount())).add(n(l.tax())));p.getItems().add(i);subtotal=subtotal.add(l.unitPrice().multiply(l.quantity()));tax=tax.add(n(l.tax()));discount=discount.add(n(l.discount()));}p.setSubtotal(subtotal);p.setTax(tax);p.setDiscount(discount);p.setTotalAmount(subtotal.add(tax).subtract(discount));}private PurchaseOrder find(UUID id){return orders.findById(id).orElseThrow(()->new NotFoundException("Purchase order",id));}private BigDecimal n(BigDecimal v){return v==null?BigDecimal.ZERO:v;}private Detail view(PurchaseOrder p){return new Detail(p.getId(),p.getPurchaseOrderNumber(),p.getSupplier().getId(),p.getSupplier().getCompanyName(),p.getOrderDate(),p.getExpectedDeliveryDate(),p.getStatus(),p.getSubtotal(),p.getDiscount(),p.getTax(),p.getTotalAmount(),p.getNotes(),p.getItems().stream().map(i->new ItemView(i.getId(),i.getMedicine().getId(),i.getMedicine().getName(),i.getQuantity(),i.getReceivedQuantity(),i.getUnitPrice(),i.getDiscount(),i.getTax(),i.getTotal())).toList());}}
